-- Daily refresh for the existing research table; no source-table writes.
CREATE TABLE public.sel_par_runs (
  selecties_tot date PRIMARY KEY,
  voltooid_op timestamptz NOT NULL,
  resultaat jsonb NOT NULL
);
ALTER TABLE public.sel_par_runs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sel_par_runs FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.sel_par_runs TO service_role;

CREATE FUNCTION public.ververs_sel_par(p_cutoff date, p_force boolean DEFAULT false, p_bronruns jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp
AS $refresh$
DECLARE v_result jsonb; v_rows bigint; v_source bigint;
BEGIN
  IF p_cutoff IS NULL OR p_cutoff >= (statement_timestamp() AT TIME ZONE 'UTC')::date THEN
    RAISE EXCEPTION 'Alleen afgesloten UTC-selectiedagen mogen worden overgezet';
  END IF;
  IF NOT pg_try_advisory_xact_lock(741206,10) THEN
    RAISE EXCEPTION 'Een sel_par-verversing is al bezig';
  END IF;
  IF NOT p_force AND EXISTS(SELECT 1 FROM public.sel_par_runs WHERE selecties_tot=p_cutoff) THEN
    RETURN jsonb_build_object('status','al_ververst','selecties_tot',p_cutoff);
  END IF;
  IF (SELECT array_agg(column_name::text ORDER BY ordinal_position)
      FROM information_schema.columns WHERE table_schema='public' AND table_name='selecties')
      IS DISTINCT FROM ARRAY['id','ticker','datum','strategie','beurs','koers','parameters','created_at','score','total_score','grafiek','rsi_monthly','rsi_label','macd_label','rr_pct','resistance','support','div_yield','atr','stop','rs','pivot','pct_from_high','pct_from_low','n_boxes','box_top','box_bottom','box_pct','n_contracties','laatste_pct','breakout','breakout_vol','stage2','eps_q_growth_pct','eps_annual_cagr_pct','inst_pct','ma200','high52w','weekdag_gemiddelde','weekdag_winrate','weekdag_p','maand_gemiddelde','maand_winrate','maand_p','kwartaal_gemiddelde','kwartaal_winrate','kwartaal_p','jaren_data','rank','fcf_yield','fcf_years','fcf_growing','fcf_consistent','rev_growth_pct','net_debt_ebitda','payout_pct','proba','rsi','macd_hist','macd_hist_slope','dist_sma50_pct','dist_sma200_pct','atr_pct','vol_ratio_20d','ret_5d','ret_20d','ret_60d','horizon_days','markt_ret_5d','roe_pct','terugverdienperiode','forward_pe','verwachte_winstgroei_pct','market_cap','analisten_count','piotroski_score','current_ratio','eps_years','eps_all_positive','eps_growth_pct','pe_ratio','pb_ratio','graham_number_ok','roc','earnings_yield','roc_rank','ey_rank','combined_rank','ebit','invested_capital','enterprise_value','sector','ps_ratio','ev_ebitda','ev_fcf','shareholder_yield','vc2_score','momentum_6m_pct','revenue_growth_pct','debt_to_equity','pcf_ratio','vwap20_pct','vwap50_pct','insider_net_shares','pred_ret_10d','pred_ret_30d','pred_ret_60d','model_versie']::text[] THEN
    RAISE EXCEPTION 'Selecties-schema gewijzigd; werk de expliciete onderzoeksmapping bij';
  END IF;
  CREATE TEMP TABLE sel_par_refresh_bron ON COMMIT DROP AS
  WITH gekozen AS (
    SELECT DISTINCT ON(ticker,datum,strategie) *
    FROM public.selecties WHERE datum::date<=p_cutoff
    ORDER BY ticker,datum,strategie,created_at ASC NULLS LAST,id
  ), herkomst AS (
    SELECT ticker,datum,strategie,count(*)::integer selectie_bron_aantal,
           array_agg(id ORDER BY created_at ASC NULLS LAST,id) selectie_bron_ids,
           CASE WHEN count(*)>1 THEN jsonb_agg(to_jsonb(b) ORDER BY created_at ASC NULLS LAST,id) END selectie_dubbele_bronrijen
    FROM public.selecties b WHERE datum::date<=p_cutoff GROUP BY ticker,datum,strategie
  )
  SELECT s."id" AS "id",
s."ticker" AS "ticker",
s."datum" AS "datum",
s."strategie" AS "strategie",
s."beurs" AS "beurs",
s."koers" AS "koers",
s."parameters" AS "parameters",
s."created_at" AS "created_at",
s."score" AS "score",
s."total_score" AS "total_score",
s."grafiek" AS "grafiek",
s."rsi_monthly" AS "rsi_monthly",
s."rsi_label" AS "rsi_label",
s."macd_label" AS "macd_label",
s."rr_pct" AS "rr_pct",
s."resistance" AS "resistance",
s."support" AS "support",
s."div_yield" AS "div_yield",
s."atr" AS "atr",
s."stop" AS "stop",
s."rs" AS "rs",
s."pivot" AS "pivot",
s."pct_from_high" AS "pct_from_high",
s."pct_from_low" AS "pct_from_low",
s."n_boxes" AS "n_boxes",
s."box_top" AS "box_top",
s."box_bottom" AS "box_bottom",
s."box_pct" AS "box_pct",
s."n_contracties" AS "n_contracties",
s."laatste_pct" AS "laatste_pct",
s."breakout" AS "breakout",
s."breakout_vol" AS "breakout_vol",
s."stage2" AS "stage2",
s."eps_q_growth_pct" AS "eps_q_growth_pct",
s."eps_annual_cagr_pct" AS "eps_annual_cagr_pct",
s."inst_pct" AS "inst_pct",
s."ma200" AS "ma200",
s."high52w" AS "high52w",
s."weekdag_gemiddelde" AS "weekdag_gemiddelde",
s."weekdag_winrate" AS "weekdag_winrate",
s."weekdag_p" AS "weekdag_p",
s."maand_gemiddelde" AS "maand_gemiddelde",
s."maand_winrate" AS "maand_winrate",
s."maand_p" AS "maand_p",
s."kwartaal_gemiddelde" AS "kwartaal_gemiddelde",
s."kwartaal_winrate" AS "kwartaal_winrate",
s."kwartaal_p" AS "kwartaal_p",
s."jaren_data" AS "jaren_data",
s."rank" AS "rank",
s."fcf_yield" AS "fcf_yield",
s."fcf_years" AS "fcf_years",
s."fcf_growing" AS "fcf_growing",
s."fcf_consistent" AS "fcf_consistent",
s."rev_growth_pct" AS "rev_growth_pct",
s."net_debt_ebitda" AS "net_debt_ebitda",
s."payout_pct" AS "payout_pct",
s."proba" AS "proba",
s."rsi" AS "rsi",
s."macd_hist" AS "macd_hist",
s."macd_hist_slope" AS "macd_hist_slope",
s."dist_sma50_pct" AS "dist_sma50_pct",
s."dist_sma200_pct" AS "dist_sma200_pct",
s."atr_pct" AS "atr_pct",
s."vol_ratio_20d" AS "vol_ratio_20d",
s."ret_5d" AS "ret_5d",
s."ret_20d" AS "ret_20d",
s."ret_60d" AS "ret_60d",
s."horizon_days" AS "horizon_days",
s."markt_ret_5d" AS "markt_ret_5d",
s."roe_pct" AS "roe_pct",
s."terugverdienperiode" AS "terugverdienperiode",
s."forward_pe" AS "forward_pe",
s."verwachte_winstgroei_pct" AS "verwachte_winstgroei_pct",
s."market_cap" AS "market_cap",
s."analisten_count" AS "analisten_count",
s."piotroski_score" AS "piotroski_score",
s."current_ratio" AS "current_ratio",
s."eps_years" AS "eps_years",
s."eps_all_positive" AS "eps_all_positive",
s."eps_growth_pct" AS "eps_growth_pct",
s."pe_ratio" AS "pe_ratio",
s."pb_ratio" AS "pb_ratio",
s."graham_number_ok" AS "graham_number_ok",
s."roc" AS "roc",
s."earnings_yield" AS "earnings_yield",
s."roc_rank" AS "roc_rank",
s."ey_rank" AS "ey_rank",
s."combined_rank" AS "combined_rank",
s."ebit" AS "ebit",
s."invested_capital" AS "invested_capital",
s."enterprise_value" AS "enterprise_value",
s."sector" AS "sector",
s."ps_ratio" AS "ps_ratio",
s."ev_ebitda" AS "ev_ebitda",
s."ev_fcf" AS "ev_fcf",
s."shareholder_yield" AS "shareholder_yield",
s."vc2_score" AS "vc2_score",
s."momentum_6m_pct" AS "momentum_6m_pct",
s."revenue_growth_pct" AS "revenue_growth_pct",
s."debt_to_equity" AS "debt_to_equity",
s."pcf_ratio" AS "pcf_ratio",
s."vwap20_pct" AS "vwap20_pct",
s."vwap50_pct" AS "vwap50_pct",
s."insider_net_shares" AS "insider_net_shares",
s."pred_ret_10d" AS "pred_ret_10d",
s."pred_ret_30d" AS "pred_ret_30d",
s."pred_ret_60d" AS "pred_ret_60d",
s."model_versie" AS "model_versie",
s.datum::date AS "selectiedatum",
s.koers::double precision AS "koers_selectiedatum",
h.selectie_bron_aantal AS "selectie_bron_aantal",
h.selectie_bron_ids AS "selectie_bron_ids",
h.selectie_dubbele_bronrijen AS "selectie_dubbele_bronrijen",
g."atr14" AS "tech_atr14",
g."atr14_pct" AS "tech_atr14_pct",
g."rsi14" AS "tech_rsi14",
g."ibs" AS "tech_ibs",
g."ma50" AS "tech_ma50",
g."ma200" AS "tech_ma200",
g."pct_from_ma50" AS "tech_pct_from_ma50",
g."pct_from_ma200" AS "tech_pct_from_ma200",
g."vol_ratio_20d" AS "tech_vol_ratio_20d",
g."high52w" AS "tech_high52w",
g."pct_from_high52w" AS "tech_pct_from_high52w",
g."bijgewerkt_op" AS "tech_bijgewerkt_op",
g."macd" AS "tech_macd",
g."macd_signaal" AS "tech_macd_signaal",
g."macd_hist" AS "tech_macd_hist",
g."bb_breedte" AS "tech_bb_breedte",
g."bb_percent_b" AS "tech_bb_percent_b",
g."stoch_k" AS "tech_stoch_k",
g."stoch_d" AS "tech_stoch_d",
g."adx14" AS "tech_adx14",
g."rel_sterkte_20d" AS "tech_rel_sterkte_20d",
g."hv20" AS "tech_hv20",
g."hv60" AS "tech_hv60",
g."dagen_sinds_low52w" AS "tech_dagen_sinds_low52w",
g."vol_ratio_50d" AS "tech_vol_ratio_50d",
g."ema8" AS "tech_ema8",
g."ema20" AS "tech_ema20",
g."pct_from_ema8" AS "tech_pct_from_ema8",
g."pct_from_ema20" AS "tech_pct_from_ema20",
g."ema8_minus_ema20" AS "tech_ema8_minus_ema20",
u."market_cap" AS "fund_market_cap",
u."trailing_pe" AS "fund_trailing_pe",
u."price_to_book" AS "fund_price_to_book",
u."dividend_yield" AS "fund_dividend_yield",
u."current_ratio" AS "fund_current_ratio",
u."revenue_growth_pct" AS "fund_revenue_growth_pct",
u."fcf_yield" AS "fund_fcf_yield",
u."fcf_years" AS "fund_fcf_years",
u."fcf_growing" AS "fund_fcf_growing",
u."fcf_consistent" AS "fund_fcf_consistent",
u."net_debt_ebitda" AS "fund_net_debt_ebitda",
u."payout_pct" AS "fund_payout_pct",
u."analisten_count" AS "fund_analisten_count",
u."piotroski_score" AS "fund_piotroski_score",
u."eps_growth_pct" AS "fund_eps_growth_pct",
u."eps_cagr_pct" AS "fund_eps_cagr_pct",
u."peg_ratio" AS "fund_peg_ratio",
u."bijgewerkt_op" AS "fund_bijgewerkt_op",
g.ticker IS NOT NULL AS "technicals_aanwezig",
u.ticker IS NOT NULL AS "fundamentals_aanwezig",
coalesce(u.bijgewerkt_op IS NOT NULL AND (u.bijgewerkt_op AT TIME ZONE 'UTC')::date<=s.datum::date,false) AS "fundamentals_tijdig_bekend",
f.ticker IS NOT NULL AS "forward_bron_aanwezig",
f.entry_koers AS "forward_entry_koers",
f.bijgewerkt_op AS "forward_bijgewerkt_op",
CASE WHEN (s.koers::double precision>0 AND s.koers::double precision<'Infinity'::double precision) AND (f.entry_koers>0 AND f.entry_koers<'Infinity'::double precision) THEN abs(s.koers::double precision/f.entry_koers-1)>.001 END AS "koersbasis_verschil",
f.fwd_close_5d AS "koers_5d",
f.fwd_ret_5d AS "bron_fwd_ret_5d",
CASE WHEN (s.koers::double precision>0 AND s.koers::double precision<'Infinity'::double precision) AND (f.fwd_close_5d>0 AND f.fwd_close_5d<'Infinity'::double precision) THEN (f.fwd_close_5d/s.koers::double precision-1)*100 END AS "rendement_5d_pct",
CASE WHEN f.fwd_close_5d IS NULL THEN 'ontbreekt_in_bron' WHEN NOT (f.fwd_close_5d>0 AND f.fwd_close_5d<'Infinity'::double precision) THEN 'ongeldige_vervolgkoers' WHEN NOT coalesce((s.koers::double precision>0 AND s.koers::double precision<'Infinity'::double precision),false) THEN 'ongeldige_selectiekoers' ELSE 'beschikbaar_uit_bron' END::text AS "status_5d",
f.fwd_close_10d AS "koers_10d",
f.fwd_ret_10d AS "bron_fwd_ret_10d",
CASE WHEN (s.koers::double precision>0 AND s.koers::double precision<'Infinity'::double precision) AND (f.fwd_close_10d>0 AND f.fwd_close_10d<'Infinity'::double precision) THEN (f.fwd_close_10d/s.koers::double precision-1)*100 END AS "rendement_10d_pct",
CASE WHEN f.fwd_close_10d IS NULL THEN 'ontbreekt_in_bron' WHEN NOT (f.fwd_close_10d>0 AND f.fwd_close_10d<'Infinity'::double precision) THEN 'ongeldige_vervolgkoers' WHEN NOT coalesce((s.koers::double precision>0 AND s.koers::double precision<'Infinity'::double precision),false) THEN 'ongeldige_selectiekoers' ELSE 'beschikbaar_uit_bron' END::text AS "status_10d",
f.fwd_close_20d AS "koers_20d",
f.fwd_ret_20d AS "bron_fwd_ret_20d",
CASE WHEN (s.koers::double precision>0 AND s.koers::double precision<'Infinity'::double precision) AND (f.fwd_close_20d>0 AND f.fwd_close_20d<'Infinity'::double precision) THEN (f.fwd_close_20d/s.koers::double precision-1)*100 END AS "rendement_20d_pct",
CASE WHEN f.fwd_close_20d IS NULL THEN 'ontbreekt_in_bron' WHEN NOT (f.fwd_close_20d>0 AND f.fwd_close_20d<'Infinity'::double precision) THEN 'ongeldige_vervolgkoers' WHEN NOT coalesce((s.koers::double precision>0 AND s.koers::double precision<'Infinity'::double precision),false) THEN 'ongeldige_selectiekoers' ELSE 'beschikbaar_uit_bron' END::text AS "status_20d",
f.fwd_close_30d AS "koers_30d",
f.fwd_ret_30d AS "bron_fwd_ret_30d",
CASE WHEN (s.koers::double precision>0 AND s.koers::double precision<'Infinity'::double precision) AND (f.fwd_close_30d>0 AND f.fwd_close_30d<'Infinity'::double precision) THEN (f.fwd_close_30d/s.koers::double precision-1)*100 END AS "rendement_30d_pct",
CASE WHEN f.fwd_close_30d IS NULL THEN 'ontbreekt_in_bron' WHEN NOT (f.fwd_close_30d>0 AND f.fwd_close_30d<'Infinity'::double precision) THEN 'ongeldige_vervolgkoers' WHEN NOT coalesce((s.koers::double precision>0 AND s.koers::double precision<'Infinity'::double precision),false) THEN 'ongeldige_selectiekoers' ELSE 'beschikbaar_uit_bron' END::text AS "status_30d",
f.fwd_close_60d AS "koers_60d",
f.fwd_ret_60d AS "bron_fwd_ret_60d",
CASE WHEN (s.koers::double precision>0 AND s.koers::double precision<'Infinity'::double precision) AND (f.fwd_close_60d>0 AND f.fwd_close_60d<'Infinity'::double precision) THEN (f.fwd_close_60d/s.koers::double precision-1)*100 END AS "rendement_60d_pct",
CASE WHEN f.fwd_close_60d IS NULL THEN 'ontbreekt_in_bron' WHEN NOT (f.fwd_close_60d>0 AND f.fwd_close_60d<'Infinity'::double precision) THEN 'ongeldige_vervolgkoers' WHEN NOT coalesce((s.koers::double precision>0 AND s.koers::double precision<'Infinity'::double precision),false) THEN 'ongeldige_selectiekoers' ELSE 'beschikbaar_uit_bron' END::text AS "status_60d",
false AS "historische_featurebeschikbaarheid_geverifieerd",
false AS "vervolgkoersdatums_onafhankelijk_geverifieerd",
statement_timestamp() AS "onderzoek_samengesteld_op"
  FROM gekozen s JOIN herkomst h USING(ticker,datum,strategie)
  LEFT JOIN public.generieke_technicals g ON g.ticker=s.ticker AND g.datum=s.datum
  LEFT JOIN public.generieke_fundamentals u ON u.ticker=s.ticker AND u.datum=s.datum
  LEFT JOIN public.forward_returns f ON f.ticker=s.ticker AND f.datum=s.datum AND f.strategie=s.strategie;
  SELECT count(*) INTO v_source FROM pg_temp.sel_par_refresh_bron;
  IF v_source=0 THEN RAISE EXCEPTION 'Geen bronselecties beschikbaar'; END IF;

  INSERT INTO public.selecties_onderzoek_strategie_bron ("id","ticker","datum","strategie","beurs","koers","parameters","created_at","score","total_score","grafiek","rsi_monthly","rsi_label","macd_label","rr_pct","resistance","support","div_yield","atr","stop","rs","pivot","pct_from_high","pct_from_low","n_boxes","box_top","box_bottom","box_pct","n_contracties","laatste_pct","breakout","breakout_vol","stage2","eps_q_growth_pct","eps_annual_cagr_pct","inst_pct","ma200","high52w","weekdag_gemiddelde","weekdag_winrate","weekdag_p","maand_gemiddelde","maand_winrate","maand_p","kwartaal_gemiddelde","kwartaal_winrate","kwartaal_p","jaren_data","rank","fcf_yield","fcf_years","fcf_growing","fcf_consistent","rev_growth_pct","net_debt_ebitda","payout_pct","proba","rsi","macd_hist","macd_hist_slope","dist_sma50_pct","dist_sma200_pct","atr_pct","vol_ratio_20d","ret_5d","ret_20d","ret_60d","horizon_days","markt_ret_5d","roe_pct","terugverdienperiode","forward_pe","verwachte_winstgroei_pct","market_cap","analisten_count","piotroski_score","current_ratio","eps_years","eps_all_positive","eps_growth_pct","pe_ratio","pb_ratio","graham_number_ok","roc","earnings_yield","roc_rank","ey_rank","combined_rank","ebit","invested_capital","enterprise_value","sector","ps_ratio","ev_ebitda","ev_fcf","shareholder_yield","vc2_score","momentum_6m_pct","revenue_growth_pct","debt_to_equity","pcf_ratio","vwap20_pct","vwap50_pct","insider_net_shares","pred_ret_10d","pred_ret_30d","pred_ret_60d","model_versie","selectiedatum","koers_selectiedatum","selectie_bron_aantal","selectie_bron_ids","selectie_dubbele_bronrijen","tech_atr14","tech_atr14_pct","tech_rsi14","tech_ibs","tech_ma50","tech_ma200","tech_pct_from_ma50","tech_pct_from_ma200","tech_vol_ratio_20d","tech_high52w","tech_pct_from_high52w","tech_bijgewerkt_op","tech_macd","tech_macd_signaal","tech_macd_hist","tech_bb_breedte","tech_bb_percent_b","tech_stoch_k","tech_stoch_d","tech_adx14","tech_rel_sterkte_20d","tech_hv20","tech_hv60","tech_dagen