  CREATE TEMP TABLE sel_par_refresh_stage ON COMMIT DROP AS
  WITH ids AS (
    SELECT ticker,datum,array_agg(i ORDER BY i) bron_ids
    FROM pg_temp.sel_par_refresh_bron b CROSS JOIN LATERAL unnest(b.selectie_bron_ids) i GROUP BY ticker,datum
  )
  SELECT min(o.id) AS "id",
o."ticker" AS "ticker",
o."datum" AS "datum",
string_agg(DISTINCT o.strategie,' | ' ORDER BY o.strategie) AS "strategie",
CASE WHEN count(DISTINCT to_jsonb(o."beurs")) FILTER(WHERE o."beurs" IS NOT NULL)<=1 THEN (array_agg(o."beurs") FILTER(WHERE o."beurs" IS NOT NULL))[1] END AS "beurs",
CASE WHEN count(DISTINCT to_jsonb(o."koers")) FILTER(WHERE o."koers" IS NOT NULL)<=1 THEN (array_agg(o."koers") FILTER(WHERE o."koers" IS NOT NULL))[1] END AS "koers",
CASE WHEN count(DISTINCT to_jsonb(o."parameters")) FILTER(WHERE o."parameters" IS NOT NULL)<=1 THEN (array_agg(o."parameters") FILTER(WHERE o."parameters" IS NOT NULL))[1] END AS "parameters",
min(o.created_at) AS "created_at",
CASE WHEN count(DISTINCT to_jsonb(o."score")) FILTER(WHERE o."score" IS NOT NULL)<=1 THEN (array_agg(o."score") FILTER(WHERE o."score" IS NOT NULL))[1] END AS "score",
CASE WHEN count(DISTINCT to_jsonb(o."total_score")) FILTER(WHERE o."total_score" IS NOT NULL)<=1 THEN (array_agg(o."total_score") FILTER(WHERE o."total_score" IS NOT NULL))[1] END AS "total_score",
CASE WHEN count(DISTINCT to_jsonb(o."grafiek")) FILTER(WHERE o."grafiek" IS NOT NULL)<=1 THEN (array_agg(o."grafiek") FILTER(WHERE o."grafiek" IS NOT NULL))[1] END AS "grafiek",
CASE WHEN count(DISTINCT to_jsonb(o."rsi_monthly")) FILTER(WHERE o."rsi_monthly" IS NOT NULL)<=1 THEN (array_agg(o."rsi_monthly") FILTER(WHERE o."rsi_monthly" IS NOT NULL))[1] END AS "rsi_monthly",
CASE WHEN count(DISTINCT to_jsonb(o."rsi_label")) FILTER(WHERE o."rsi_label" IS NOT NULL)<=1 THEN (array_agg(o."rsi_label") FILTER(WHERE o."rsi_label" IS NOT NULL))[1] END AS "rsi_label",
CASE WHEN count(DISTINCT to_jsonb(o."macd_label")) FILTER(WHERE o."macd_label" IS NOT NULL)<=1 THEN (array_agg(o."macd_label") FILTER(WHERE o."macd_label" IS NOT NULL))[1] END AS "macd_label",
CASE WHEN count(DISTINCT to_jsonb(o."rr_pct")) FILTER(WHERE o."rr_pct" IS NOT NULL)<=1 THEN (array_agg(o."rr_pct") FILTER(WHERE o."rr_pct" IS NOT NULL))[1] END AS "rr_pct",
CASE WHEN count(DISTINCT to_jsonb(o."resistance")) FILTER(WHERE o."resistance" IS NOT NULL)<=1 THEN (array_agg(o."resistance") FILTER(WHERE o."resistance" IS NOT NULL))[1] END AS "resistance",
CASE WHEN count(DISTINCT to_jsonb(o."support")) FILTER(WHERE o."support" IS NOT NULL)<=1 THEN (array_agg(o."support") FILTER(WHERE o."support" IS NOT NULL))[1] END AS "support",
CASE WHEN count(DISTINCT to_jsonb(o."div_yield")) FILTER(WHERE o."div_yield" IS NOT NULL)<=1 THEN (array_agg(o."div_yield") FILTER(WHERE o."div_yield" IS NOT NULL))[1] END AS "div_yield",
CASE WHEN count(DISTINCT to_jsonb(o."atr")) FILTER(WHERE o."atr" IS NOT NULL)<=1 THEN (array_agg(o."atr") FILTER(WHERE o."atr" IS NOT NULL))[1] END AS "atr",
CASE WHEN count(DISTINCT to_jsonb(o."stop")) FILTER(WHERE o."stop" IS NOT NULL)<=1 THEN (array_agg(o."stop") FILTER(WHERE o."stop" IS NOT NULL))[1] END AS "stop",
CASE WHEN count(DISTINCT to_jsonb(o."rs")) FILTER(WHERE o."rs" IS NOT NULL)<=1 THEN (array_agg(o."rs") FILTER(WHERE o."rs" IS NOT NULL))[1] END AS "rs",
CASE WHEN count(DISTINCT to_jsonb(o."pivot")) FILTER(WHERE o."pivot" IS NOT NULL)<=1 THEN (array_agg(o."pivot") FILTER(WHERE o."pivot" IS NOT NULL))[1] END AS "pivot",
CASE WHEN count(DISTINCT to_jsonb(o."pct_from_high")) FILTER(WHERE o."pct_from_high" IS NOT NULL)<=1 THEN (array_agg(o."pct_from_high") FILTER(WHERE o."pct_from_high" IS NOT NULL))[1] END AS "pct_from_high",
CASE WHEN count(DISTINCT to_jsonb(o."pct_from_low")) FILTER(WHERE o."pct_from_low" IS NOT NULL)<=1 THEN (array_agg(o."pct_from_low") FILTER(WHERE o."pct_from_low" IS NOT NULL))[1] END AS "pct_from_low",
CASE WHEN count(DISTINCT to_jsonb(o."n_boxes")) FILTER(WHERE o."n_boxes" IS NOT NULL)<=1 THEN (array_agg(o."n_boxes") FILTER(WHERE o."n_boxes" IS NOT NULL))[1] END AS "n_boxes",
CASE WHEN count(DISTINCT to_jsonb(o."box_top")) FILTER(WHERE o."box_top" IS NOT NULL)<=1 THEN (array_agg(o."box_top") FILTER(WHERE o."box_top" IS NOT NULL))[1] END AS "box_top",
CASE WHEN count(DISTINCT to_jsonb(o."box_bottom")) FILTER(WHERE o."box_bottom" IS NOT NULL)<=1 THEN (array_agg(o."box_bottom") FILTER(WHERE o."box_bottom" IS NOT NULL))[1] END AS "box_bottom",
CASE WHEN count(DISTINCT to_jsonb(o."box_pct")) FILTER(WHERE o."box_pct" IS NOT NULL)<=1 THEN (array_agg(o."box_pct") FILTER(WHERE o."box_pct" IS NOT NULL))[1] END AS "box_pct",
CASE WHEN count(DISTINCT to_jsonb(o."n_contracties")) FILTER(WHERE o."n_contracties" IS NOT NULL)<=1 THEN (array_agg(o."n_contracties") FILTER(WHERE o."n_contracties" IS NOT NULL))[1] END AS "n_contracties",
CASE WHEN count(DISTINCT to_jsonb(o."laatste_pct")) FILTER(WHERE o."laatste_pct" IS NOT NULL)<=1 THEN (array_agg(o."laatste_pct") FILTER(WHERE o."laatste_pct" IS NOT NULL))[1] END AS "laatste_pct",
CASE WHEN count(DISTINCT to_jsonb(o."breakout")) FILTER(WHERE o."breakout" IS NOT NULL)<=1 THEN (array_agg(o."breakout") FILTER(WHERE o."breakout" IS NOT NULL))[1] END AS "breakout",
