CASE WHEN count(DISTINCT to_jsonb(o."stage2")) FILTER(WHERE o."stage2" IS NOT NULL)<=1 THEN (array_agg(o."stage2") FILTER(WHERE o."stage2" IS NOT NULL))[1] END AS "stage2",
CASE WHEN count(DISTINCT to_jsonb(o."eps_q_growth_pct")) FILTER(WHERE o."eps_q_growth_pct" IS NOT NULL)<=1 THEN (array_agg(o."eps_q_growth_pct") FILTER(WHERE o."eps_q_growth_pct" IS NOT NULL))[1] END AS "eps_q_growth_pct",
CASE WHEN count(DISTINCT to_jsonb(o."eps_annual_cagr_pct")) FILTER(WHERE o."eps_annual_cagr_pct" IS NOT NULL)<=1 THEN (array_agg(o."eps_annual_cagr_pct") FILTER(WHERE o."eps_annual_cagr_pct" IS NOT NULL))[1] END AS "eps_annual_cagr_pct",
CASE WHEN count(DISTINCT to_jsonb(o."inst_pct")) FILTER(WHERE o."inst_pct" IS NOT NULL)<=1 THEN (array_agg(o."inst_pct") FILTER(WHERE o."inst_pct" IS NOT NULL))[1] END AS "inst_pct",
CASE WHEN count(DISTINCT to_jsonb(o."ma200")) FILTER(WHERE o."ma200" IS NOT NULL)<=1 THEN (array_agg(o."ma200") FILTER(WHERE o."ma200" IS NOT NULL))[1] END AS "ma200",
CASE WHEN count(DISTINCT to_jsonb(o."high52w")) FILTER(WHERE o."high52w" IS NOT NULL)<=1 THEN (array_agg(o."high52w") FILTER(WHERE o."high52w" IS NOT NULL))[1] END AS "high52w",
CASE WHEN count(DISTINCT to_jsonb(o."weekdag_gemiddelde")) FILTER(WHERE o."weekdag_gemiddelde" IS NOT NULL)<=1 THEN (array_agg(o."weekdag_gemiddelde") FILTER(WHERE o."weekdag_gemiddelde" IS NOT NULL))[1] END AS "weekdag_gemiddelde",
